import { createFileRoute, Await } from '@tanstack/react-router'
import { Suspense } from 'react'
import type { DashboardMetrics } from '#/lib/dashboard'

// Simulate a slow database query with a 2-second delay
function fetchDashboardMetrics(): Promise<DashboardMetrics> {
  return new Promise((resolve) =>
    setTimeout(() => resolve({ revenue: 15000, users: 420 }), 2000),
  )
}

export const Route = createFileRoute('/dashboard')({
  loader: () => {
    // Return the promise WITHOUT awaiting it so it can be streamed
    const metricsPromise = fetchDashboardMetrics()
    return { metricsPromise }
  },
  component: Dashboard,
})

function Dashboard() {
  const { metricsPromise } = Route.useLoaderData()

  return (
    <main className="page-wrap px-4 pb-8 pt-14">
      <section className="island-shell rise-in relative overflow-hidden rounded-[2rem] px-6 py-10 sm:px-10 sm:py-14">
